/**
 * Text utilities.
 */

export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

export function parseVersion(v: string): number {
  return Number(v.split(".")[0]);
}

export function countVowels(s: string): number {
  return s
    .toLowerCase()
    .split("")
    .filter((c) => "aeiou".includes(c)).length;
}
